"use strict";

let shopData = null;
let localCooldown = [0, 0, 0, 0, 0];
let initialized = false;
let WaveState = null;
const ENHANCE_UNLOCK_GOAL = 5;
let enhanceUnlocked = false;
let lastEnhanceProgress = null;
let enhancePicking = false;

(function () {
    GameEvents.Subscribe("shop_data_update", OnServerShopData);
    GameEvents.Subscribe("game_end", OnGameEndReset);
    GameEvents.Subscribe("game_start", OnGameStartReset);
    GameEvents.Subscribe("shop1_enhance_show", OnEnhancePickStart);
    GameEvents.Subscribe("shop1_enhance_close", OnEnhancePickEnd);
    //  $.Msg("[INPUT] Register CustomGameSynthesize command");
    Game.AddCommand("CustomGameSummon", OnSummonCommandPressed, "", 0);
    Game.AddCommand("CustomGameEnhance", OnEnhanceCommandPressed, "", 0);
    // Game.AddCommand("CustomGameSynthesize", OnSynthesizeCommandPressed, "", 0);

    CustomNetTables.SubscribeNetTableListener("wave_info", (table, key, data) => {
        if (key === "state") {
            WaveState = data;
            UpdateEnhanceUnlockState();
        }
    });

    const initialState = CustomNetTables.GetTableValue("wave_info", "state");
    if (initialState) {
        WaveState = initialState;
        UpdateEnhanceUnlockState();
    }
})();

function OnGameEndReset() {
    enhanceUnlocked = false;
    WaveState = null;
    lastEnhanceProgress = null;
    enhancePicking = false;
}

function OnGameStartReset() {
    enhanceUnlocked = false;
    WaveState = null;
    lastEnhanceProgress = null;
    enhancePicking = false;
}

function OnSummonCommandPressed() {
    OnShopBuy(1);
}

function OnEnhanceCommandPressed() {
    OnShopBuy(2);
}

function OnSynthesizeCommandPressed() {
    OnShopBuy(3);
}

function OnShopEnhancePressed() {
    const pid = Players.GetLocalPlayer();
    GameEvents.SendCustomGameEventToServer("shop1_enhance_request", {
        PlayerID: pid,
    });
}

function OnSynthesizePressed() {
    const pid = Players.GetLocalPlayer();
    // $.Msg("[INPUT] CustomGameSynthesize PRESSED, pid =", pid);

    GameEvents.SendCustomGameEventToServer("synthesize", {
        PlayerID: pid,
        _debug_time: Game.GetGameTime()
    });

    // $.Msg("[INPUT] synthesize event SENT");
}

function GetDesc(id) {
    const key = "#shop1_" + id + "_desc";
    const localized = $.Localize(key);

    if (localized && localized !== key) {
        return localized;
    }

    return "";
}

function GetEnhanceRemaining() {
    const progress = WaveState ? (WaveState.expansion_progress || 0) : 0;
    const remain = ENHANCE_UNLOCK_GOAL - progress;
    return remain > 0 ? remain : 0;
}

function IsEnhanceUnlocked() {
    return enhanceUnlocked || GetEnhanceRemaining() <= 0;
}

function GetEnhanceLockedTooltip() {
    const remain = GetEnhanceRemaining();
    return $.Localize("#shop1_enhance_unlock_tip_1") + " " + remain + " " + $.Localize("#shop1_enhance_unlock_tip_2");
}

function UpdateEnhanceUnlockState() {
    const progress = WaveState ? (WaveState.expansion_progress || 0) : null;
    if (progress === null) return;

    if (!enhanceUnlocked) {
        if (progress >= ENHANCE_UNLOCK_GOAL) {
            enhanceUnlocked = true;
        } else if (lastEnhanceProgress !== null
            && progress < lastEnhanceProgress
            && lastEnhanceProgress >= ENHANCE_UNLOCK_GOAL - 1) {
            enhanceUnlocked = true;
        }
    }

    lastEnhanceProgress = progress;
}

function BindHoverTooltip(id) {
    const icon = $("#Shop" + id);
    if (!icon) return;

    if (icon.desc_bound) return;
    icon.desc_bound = true;

    icon.SetPanelEvent("onmouseover", function () {
        if (id === 2) {
            const tip = IsEnhanceUnlocked()
                ? $.Localize("#shop1_2_desc")
                : GetEnhanceLockedTooltip();
            $.DispatchEvent("DOTAShowTextTooltip", icon, tip);
            return;
        }
        const text = GetDesc(id);
        if (text && text !== "") {
            $.DispatchEvent("DOTAShowTextTooltip", icon, text);
        }
    });

    icon.SetPanelEvent("onmouseout", function () {
        $.DispatchEvent("DOTAHideTextTooltip", icon);
    });
}

function OnEnhancePickStart(event) {
    if (!event || event.player_id !== Players.GetLocalPlayer()) {
        return;
    }
    enhancePicking = true;
    UpdateUI();
}

function OnEnhancePickEnd(event) {
    if (!event || event.player_id !== Players.GetLocalPlayer()) {
        return;
    }
    enhancePicking = false;
    UpdateUI();
}

// 接收到服务器配置 → 显示 ShopBar
function OnServerShopData(data) {
    shopData = data;

    // 第一次收到数据 → 显示
    if (!initialized) {

        $("#ShopBar").RemoveClass("Hidden");
        $("#ShopBar").AddClass("Visible");
        initialized = true;
    }

    UpdateUI();
    StartThink();
}

// 每帧冷却更新
function StartThink() {
    $.Schedule(0.03, function () {
        UpdateUI();
        StartThink();
    });
}

// 更新 价格、冷却、解锁
function UpdateUI() {
    if (!shopData) return;

    const now = Game.GetGameTime();

    for (let i = 1; i <= 5; i++) {
        const info = shopData.items[i];
        if (!info) continue;

        BindHoverTooltip(i)

        $("#Name" + i).text = info.name || "";

        // 显示价格
        if (info.price == 0) {
            $("#Price" + i).text = "";
        } else {
            $("#Price" + i).text = info.price;
        }

        // 解锁时间
        const unlocked = now >= info.unlock_time;

        const slot = $("#Shop" + i);
        const mask = $("#Mask" + i);
        const text = $("#CD" + i);

        if (!slot) continue;

        if (enhancePicking) {
            slot.SetHasClass("disabled", true);
            slot.hittest = false;
            mask.visible = true;
            mask.style.transform = "rotateZ(0deg)";
            text.text = "";
            continue;
        }

        // 未解锁 → 全遮罩（不显示倒计时文本）
        if (!unlocked) {
            const remain = info.unlock_time - now;

            slot.SetHasClass("disabled", true);
            slot.hittest = false;
            mask.visible = true;

            $("#Price" + i).visible = false;
            // 旋转遮罩（与 0.5s 本地冷却一致，不过 CD 比例不一样）
            const full = info.unlock_delay || 1;
            const pct = Math.max(remain / full, 0);
            mask.style.transform = "rotateZ(" + (360 * pct) + "deg)";

            // 显示剩余秒数
            text.text = Math.ceil(remain);

            continue;
        }

        // 解锁 → 本地 0.5s 冷却
        const remain = Math.max(localCooldown[i - 1] - now, 0);

        if (remain > 0) {
            slot.SetHasClass("disabled", true);
            slot.hittest = false;
            mask.visible = true;
            mask.style.transform = "rotateZ(" + (360 * remain / 0.5) + "deg)";
            text.text = Math.ceil(remain * 10) / 10;
        }
        else {
            slot.SetHasClass("disabled", false);
            slot.hittest = true;
            $("#Price" + i).visible = true;
            mask.visible = false;
            text.text = "";
        }
    }
}

// 点击购买
function OnShopBuy(id) {
    if (!shopData) return;
    if (enhancePicking) return;

    const info = shopData.items[id];
    const now = Game.GetGameTime();

    // 未解锁
    if (now < info.unlock_time)
        return;

    // 本地冷却中
    if (localCooldown[id - 1] > now) {
        Game.EmitSound("General.Cancel");
        return;
    }

    if (id === 2) {
        if (!IsEnhanceUnlocked()) {
            const panel = $("#Shop2");
            if (panel) {
                $.DispatchEvent("DOTAShowTextTooltip", panel, GetEnhanceLockedTooltip());
            }
            return;
        }
        OnShopEnhancePressed();
        return;
    }

    if (id === 3) {
        OnSynthesizePressed();
        return;
    }

    // 请求服务器扣金币 + 购买
    GameEvents.SendCustomGameEventToServer("shop_buy_request", {
        id: id,
    });

    UpdateUI();
}

// 服务器回传购买成功（更新等级）
GameEvents.Subscribe("shop_buy_success", function (data) {
    shopData.items[data.id].level = data.level;
    let now = Game.GetGameTime();
    localCooldown[data.id - 1] = now + 0.5;
});

